    import heapq
    n, m = map(int, input().split())
    adj = [[] for _ in range(n + 1)]
    for _ in range(m):
        u, v, w = map(int, input().split()); adj[u].append((v, w))
    d = [float("inf")] * (n + 1); d[1] = 0; pq = [(0, 1)]
    while pq:
        du, u = heapq.heappop(pq)
        if du > d[u]: continue
